using HRIS.Api.Data; using HRIS.Api.Models; using Microsoft.EntityFrameworkCore;
namespace HRIS.Api.Repositories;
public class ParkingRepository : IParkingRepository { private readonly AppDbContext _db; public ParkingRepository(AppDbContext db)=>_db=db; public Task<List<VehicleType>> GetVehicleTypesAsync()=>_db.VehicleTypes.OrderBy(x=>x.Name).ToListAsync(); public Task<List<ParkingRegistration>> GetAllAsync(int? employeeId=null)=>_db.ParkingRegistrations.Include(x=>x.Employee).Include(x=>x.VehicleType).Where(x=>employeeId==null||x.EmployeeId==employeeId).OrderByDescending(x=>x.CreatedAt).ToListAsync(); public Task<ParkingRegistration?> GetByIdAsync(int id)=>_db.ParkingRegistrations.Include(x=>x.Employee).Include(x=>x.VehicleType).FirstOrDefaultAsync(x=>x.Id==id); public Task<bool> ActivePlateExistsAsync(string plate,int? exceptId=null)=>_db.ParkingRegistrations.AnyAsync(x=>x.PlateNumber==plate && x.Status!="Rejected" && x.Status!="Cancelled" && (exceptId==null||x.Id!=exceptId)); public async Task<ParkingRegistration> AddAsync(ParkingRegistration x){_db.ParkingRegistrations.Add(x);await _db.SaveChangesAsync();return x;} public async Task UpdateAsync(ParkingRegistration x)=>await _db.SaveChangesAsync(); }
